#!/usr/bin/env python3
from __future__ import annotations
from pathlib import Path
from reportlab.lib.enums import TA_CENTER, TA_JUSTIFY, TA_LEFT
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
from reportlab.lib.units import cm
from reportlab.platypus import PageBreak, Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle, KeepTogether, ListFlowable, ListItem
ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / 'docs' / 'CarbyneSentinel_Implementation_Plan.pdf'

def styles():
    base = getSampleStyleSheet()
    s = {'cover': ParagraphStyle('cover', parent=base['Normal'], fontName='Helvetica-Bold', fontSize=16, leading=20, alignment=TA_CENTER, spaceAfter=8), 'sub': ParagraphStyle('sub', parent=base['Normal'], fontName='Helvetica', fontSize=10, leading=13, alignment=TA_CENTER, spaceAfter=4), 'h1': ParagraphStyle('h1', parent=base['Heading1'], fontName='Helvetica-Bold', fontSize=12.5, leading=16, spaceBefore=16, spaceAfter=8, textColor='black'), 'h2': ParagraphStyle('h2', parent=base['Heading2'], fontName='Helvetica-Bold', fontSize=11, leading=14, spaceBefore=12, spaceAfter=5, textColor='black'), 'h3': ParagraphStyle('h3', parent=base['Heading3'], fontName='Helvetica-Bold', fontSize=10, leading=13, spaceBefore=8, spaceAfter=4, textColor='black'), 'body': ParagraphStyle('body', parent=base['Normal'], fontName='Helvetica', fontSize=10, leading=14, alignment=TA_JUSTIFY, spaceAfter=7), 'bullet': ParagraphStyle('bullet', parent=base['Normal'], fontName='Helvetica', fontSize=10, leading=13.5, leftIndent=0), 'mono': ParagraphStyle('mono', parent=base['Normal'], fontName='Courier', fontSize=7.5, leading=9.5, spaceAfter=4), 'caption': ParagraphStyle('caption', parent=base['Normal'], fontName='Helvetica-Oblique', fontSize=8, leading=10, spaceBefore=2, spaceAfter=8), 'footer': ParagraphStyle('footer', parent=base['Normal'], fontName='Helvetica', fontSize=8, alignment=TA_CENTER), 'cell': ParagraphStyle('cell', parent=base['Normal'], fontName='Helvetica', fontSize=7.5, leading=9.5), 'cellb': ParagraphStyle('cellb', parent=base['Normal'], fontName='Helvetica-Bold', fontSize=7.5, leading=9.5)}
    return s

def bullets(items, st):
    return ListFlowable([ListItem(Paragraph(i, st['bullet']), leftIndent=10, bulletColor='black') for i in items], bulletType='bullet', start='-', leftIndent=14, spaceBefore=1, spaceAfter=4)

def numbered(items, st):
    return ListFlowable([ListItem(Paragraph(i, st['bullet']), leftIndent=10, value=n) for n, i in enumerate(items, 1)], bulletType='1', leftIndent=16, spaceBefore=1, spaceAfter=4)

def table(headers, rows, st, widths):
    data = [[Paragraph(h, st['cellb']) for h in headers]]
    for r in rows:
        data.append([Paragraph(str(c), st['cell']) for c in r])
    t = Table(data, colWidths=widths, repeatRows=1)
    t.setStyle(TableStyle([('GRID', (0, 0), (-1, -1), 0.4, 'black'), ('BACKGROUND', (0, 0), (-1, 0), 'white'), ('VALIGN', (0, 0), (-1, -1), 'TOP'), ('LEFTPADDING', (0, 0), (-1, -1), 3), ('RIGHTPADDING', (0, 0), (-1, -1), 3), ('TOPPADDING', (0, 0), (-1, -1), 3), ('BOTTOMPADDING', (0, 0), (-1, -1), 3)]))
    return t

def footer(canvas, doc):
    canvas.saveState()
    canvas.setFont('Helvetica', 8)
    canvas.drawCentredString(A4[0] / 2, 1.2 * cm, f'CarbyneSentinel Implementation Plan  |  page {doc.page}')
    canvas.restoreState()

def build():
    st = styles()
    OUT.parent.mkdir(parents=True, exist_ok=True)
    doc = SimpleDocTemplate(str(OUT), pagesize=A4, leftMargin=2.0 * cm, rightMargin=2.0 * cm, topMargin=1.8 * cm, bottomMargin=2.0 * cm, title='CarbyneSentinel Implementation Plan', author='CarbyneSentinel FYP Team')
    story = []
    P = lambda t: story.append(Paragraph(t, st['body']))
    H1 = lambda t: story.append(Paragraph(t, st['h1']))
    H2 = lambda t: story.append(Paragraph(t, st['h2']))
    H3 = lambda t: story.append(Paragraph(t, st['h3']))
    SP = lambda n=6: story.append(Spacer(1, n))
    story.append(Spacer(1, 3 * cm))
    story.append(Paragraph('CARBYNESENTINEL', st['cover']))
    story.append(Paragraph('Implementation Plan', st['cover']))
    SP(10)
    story.append(Paragraph('Final Year Project — BS Computer Science', st['sub']))
    story.append(Paragraph('National University of Computer and Emerging Sciences, Lahore', st['sub']))
    SP(16)
    story.append(Paragraph('Adeena Riaz (23L-2501)', st['sub']))
    story.append(Paragraph('Ali Asad Khan (23L-0802)', st['sub']))
    story.append(Paragraph('Maryam Amanat Ali Butt (23L-0779)', st['sub']))
    SP(8)
    story.append(Paragraph('Supervisor: Usman Aamer', st['sub']))
    SP(20)
    story.append(Paragraph('Internal working document for the team. Black and white. No marketing language. Synced to the master roadmap (Steps 1-15, Tracks A/B, dataset map). Research gaps and paper links stay tied to main.tex. Public paper stays conservative; this plan is the full internal build target.', st['body']))
    story.append(PageBreak())
    H1('1. Purpose of this plan')
    P('This document is the shared implementation plan for CarbyneSentinel. It tells the three-person team what to build, in what order, why each piece exists in research terms, what already exists in the dataset repo, and how we will know a stage is done. It does not assign named owners. Anyone can pick the next open deliverable; the sequence and acceptance criteria stay the same.')
    P('CarbyneSentinel is a passive pre-confirmation watcher on an Ethereum test network (e.g. Sepolia). Pending mempool traffic is admitted, EVM bytecode is turned into a Control Flow Graph (CFG) and an opcode sequence, a Graph Convolutional Network (GCN) and a LoRA-tuned Qwen2.5-Coder model score structure and semantics, a manipulation fingerprint flags deliberately disguised code, and a fused risk score raises a human review flag. We do not cancel transactions, halt validators, or mutate chain state. Latency target on the hot path is under 500 ms.')
    P('Two scopes exist on purpose. The public/submitted proposal (main.tex / advisor .docx) stays conservative: mempool screening + hybrid GCN+LLM, SmartBugs/SolidiFI, sub-500 ms, four-stage diagram. The real internal build target is the full master roadmap (Steps 1-15): fingerprint detector, AgentGuard adapter, obfuscation benchmark, DeFi-Intent-Bench, dashboard (Firebase), evaluation, and dataset publishing. This plan syncs to the internal roadmap while keeping the paper claims safe.')
    P('Sources: submitted FYP report (main.tex), internal master roadmap (tracks + Steps 1-15 + dataset map), data/processed/, target_schema.json (including transformation fields).')
    H1('2. System picture (one page)')
    H2('2.1 Online path (runtime) — Contract Adapter')
    story.append(numbered(['Listen to pending transactions on Sepolia (WebSocket / RPC).', 'Counting Bloom filter: drop duplicates / absorb spam (Step 6 / Track B).', 'Bytecode reader: disassemble to opcodes; build CFG (Step 1).', 'Manipulation fingerprint: score deliberate disguise / obfuscation look (Step 2).', 'GCN structural detector on CFG (Step 3 — upgrade simplified stand-in to trained model).', 'LoRA Qwen2.5-Coder semantic / intent auditor (Step 4).', 'Fusion of structural + semantic + fingerprint -> risk in [0, 1] (Step 5).', 'If score >= threshold: flag + log; async write alert to Firebase for dashboard. Else: log only.'], st))
    H2('2.2 Parallel adapters (same brain)')
    story.append(bullets(['Contract Adapter (Step 7): Steps 1-6 on smart-contract mempool traffic — core FYP path.', 'AgentGuard / Agent-Payment Adapter (Step 8): reuse Steps 1-5 on AI-agent payment intents.', 'Bridge Adapter (Step 9): design-only sketch this cycle — do not implement as a product.', 'Dashboard (Step 10): live scored stream for demos — Firebase-backed alerts UI.'], st))
    H2('2.3 Offline path (training and datasets)')
    story.append(numbered(['Use processed corpora (SolidiFI, SmartBugs, DIVE, DAppSCAN, DeFiHackLabs, Slither benign, DeFi-Intent-Bench seed).', 'Measure class imbalance; augment minority classes with controlled transforms.', 'Scale obfuscation benchmark (Step 11): parent -> disguised + exploit re-verified.', 'Grow DeFi-Intent-Bench (Step 12): exploit / benign_transfer / benign_arbitrage traces.', 'Train GCN; LoRA-adapt Qwen2.5-Coder; calibrate fusion including fingerprint signal.', 'Full evaluation (Step 13); optional publish (Step 14); report and defense (Step 15).'], st))
    H2('2.4 Out of scope (do not build this cycle)')
    story.append(bullets(['Mainnet funds, private key custody, automated on-chain pause / cancel.', 'Full Bridge Adapter product (Step 9 stays design-only).', 'Full Solidity decompilation on the hot path.', 'Claiming Forta-level production SLAs; Forta is industry context, not our stack.'], st))
    H1('3. Research framing: gaps we fill')
    P("No single reviewed system combines counting Bloom filter intake, bytecode CFG + GCN, grounded LLM checking, and a timed pre-confirmation path under 500 ms. That is the research claim of CarbyneSentinel. The table below is the team's working map from paper to engineering action.")
    story.append(table(['Paper / source', 'What it gives us', 'What it does not give us', 'Our action'], [['Haq et al. Carbyne (arXiv 2025)', 'Counting Bloom filter mempool intake idea; DoS-resilient admission', 'Not a vuln detector; Bitcoin-main results; CarbEth not measured', 'Build Ethereum testnet intake with CBF; measure separately'], ['Durieux et al. SmartBugs (ICSE 2020)', 'Shared eval harness; curated labels', 'Offline only; no mempool path', 'Primary detection benchmark track'], ['Ghaleb & Pattabiraman SolidiFI (ISSTA 2020)', 'Injected bugs with precise labels', 'Not a detector; not live screening', 'Primary detection benchmark + seed for augmentation'], ['Zhuang / Liu GNN & CGE', 'GCN/GNN work for contract vulns; hybrid with expert features', 'Usually Solidity/source graphs; offline', 'GCN on bytecode CFG; do not copy source IR path'], ['Luo et al. SCVHunter (ICSE 2024)', 'Heterogeneous graph attention; strong offline F1', 'Needs source/IR; no LLM; no latency budget', 'Borrow graph intuition; hot path stays bytecode'], ['Dai et al. ORACAL', 'Multimodal graph + LLM/RAG; explainability ideas', 'Needs Solidity for DFG/CG; not timed to 500 ms', 'Keep hybrid idea; stay bytecode-first on hot path'], ['Sun et al. GPTScan; Liu et al. PropertyGPT', 'LLM needs grounding / second check; RAG habits', 'Source projects; seconds-level latency', 'Use short opcode prompts + GCN as second vote; LoRA Qwen locally'], ['Liu et al. FinDet (arXiv 2025)', 'Bytecode + LLM; semantic lift; uncertainty', 'Contract-level adversarial label; no GCN+CBF stack', 'Borrow lift/uncertainty ideas for LLM branch'], ['Sheng et al. OBFPROBE (arXiv 2025)', 'Obfuscation breaks detectors; taxonomy of tricks', 'Ranking tool, not fused pending score', 'Build verified obfuscation bench; fingerprint signal'], ['Daian Flash Boys; Qin flash loans; Wu DeFiRanger', 'Pending stage matters; intent vs structure; DeFi semantics', 'Not our hybrid detector', 'DeFi-Intent-Bench + semantic LLM questions'], ['Forta Firewall docs', 'Industry proof that pre-inclusion scoring exists', 'Closed methods; vendor metrics', 'Cite as motivation; evaluate ourselves on open sets']], st, [3.2 * cm, 4.0 * cm, 4.0 * cm, 4.3 * cm]))
    story.append(Paragraph('Table 1. Paper-to-action map for implementation.', st['caption']))
    H2('3.1 Enhancements over existing projects (say this clearly)')
    story.append(bullets(['Pending-path system, not another offline Solidity scanner.', 'Bytecode CFG + GCN (structure) fused with LoRA Qwen2.5-Coder (semantics), not LLM-only or GNN-only.', 'Counting Bloom filter intake adapted from Carbyne-style mempool thinking to our Ethereum testnet watcher.', 'Obfuscation-aware evaluation and dataset construction (OBFPROBE gap): verified parent/transform pairs in our schema.', 'Class-imbalance-aware augmentation that grows our own dataset over time, not one-shot training on majority tags only.', 'Passive flag only — research prototype, not a closed commercial firewall.'], st))
    H1('4. Model choices (locked for v1)')
    H2('4.1 Structural: GCN')
    P('Use a Graph Convolutional Network over the bytecode-derived CFG. Input: PyTorch Geometric style graph (node features per basic block, edge_index for jumps / fall-through). Output: structural risk logit or embedding. This follows the GNN line (Zhuang, Liu CGE, SCVHunter) but starts from EVM bytecode, not Solidity IR.')
    P('v1 recommendation: 2–3 GCN layers, modest hidden size (e.g. 64–128), global pool (mean / max), MLP head. Train with class-weighted loss because the corpus is imbalanced. Keep a checkpoint that runs on CPU if GPU is unavailable for demo.')
    H2('4.2 Semantic: Qwen2.5-Coder + LoRA')
    P('Best pick for the LLM branch: Qwen2.5-Coder (smallest practical size that fits team hardware; prefer 1.5B/3B/7B depending on VRAM). Adapt with LoRA (Low-Rank Adaptation) so we do not full-finetune the base model. Prompts use normalised opcode sequences or short snippets, not entire Solidity projects (unlike GPTScan).')
    P('v1 LoRA defaults to try: rank 8–16, alpha 16–32, dropout 0.05, target modules attention projections. Quantisation (4-bit / 8-bit) allowed for training and inference if needed for the 500 ms budget. Always keep a deterministic stub scorer for CI when the model weights are not loaded.')
    H2('4.3 Fingerprint + Fusion')
    P('Keep the Manipulation Fingerprint Detector (roadmap Step 2) as a third signal: how disguised the bytecode looks versus normal code. Late-fuse GCN, LLM, and fingerprint into a small MLP or calibrated weighted sum. Log all raw scores. Tune threshold on SmartBugs + SolidiFI (and obfuscation pairs for evasion). Ablations: GCN-only, LLM-only, fingerprint-only, and full fuse.')
    H1('5. Data status (what is already done)')
    P('Do not re-download or re-invent the ingestion layer for public corpora unless a bug is found. Current processed state (approximate, from the dataset repo):')
    story.append(table(['Corpus', 'Role', 'Approx. size', 'Status'], [['SolidiFI + SmartBugs master', 'Gold / injected labels; compile path', '493 vuln', 'Done'], ['DIVE vulnerable', 'Scale for GNN', '~19.6k', 'Done'], ['DIVE benign', 'Benign pool', '~2.7k', 'Done'], ['DAppSCAN', 'Audit-based vuln', '~5k', 'Done'], ['DeFiHackLabs', 'Real exploit PoCs', '~848', 'Done'], ['Slither HF benign', 'Large tool-clean pool', '~35.1k', 'Done'], ['DeFi-Intent-Bench', 'Exploit vs transfer vs arb (Step 12)', '150 seed (50/50/50)', 'Seed done; enrich next'], ['Obfuscation benchmark', 'Disguised + re-verified pairs (Step 11)', 'Small-scale tool exists', 'Scale up next']], st, [4.0 * cm, 4.5 * cm, 3.5 * cm, 3.5 * cm]))
    story.append(Paragraph('Table 2. Dataset inventory (synced to master roadmap).', st['caption']))
    P('Roadmap dataset roles: SolidiFI/SmartBugs = gold seeds + obfuscation base; DeFiHackLabs = real exploits + exploit half of intent bench; Slither HF = benign pool; DAppSCAN = audit cross-check; Etherscan/Dune = live benign-arbitrage traces when API keys allow; custom obfuscation bench = publishable contribution for the fingerprint thesis; DeFi-Intent-Bench = train/test Step 4 intent reasoning.')
    H2('5.1 Class imbalance (confirmed)')
    P('Across processed vulnerable tags we observe about 13 vulnerability classes. Majority mass sits in AccessControl, Other, Reentrancy, Arithmetic. Minority classes (TxOrigin, TimeManipulation, FrontRunning, BadRandomness, DoS, ShortAddress, Flashloan, OracleManipulation, etc.) need augmentation. A model trained without rebalancing will lazy-predict majority classes. Augmentation is therefore both a training fix and the seed of our custom obfuscation dataset.')
    H2('5.2 Schema for originals and transforms')
    P('All new records (especially augmented / obfuscated ones) must follow target_schema.json. Critical transformation fields:')
    story.append(bullets(['parent_contract_id — null for seeds; set for variants.', 'transformation_level — lexical | structural | control_flow | data_flow | contract_level | none.', 'transformation_techniques — list, e.g. dead_code_insertion, opaque_predicate.', 'obfuscation_severity — light | moderate | aggressive | none.', 'exploit_verified_after_transform — true/false/null after fork-replay or PoC check.'], st))
    H1('6. Phased implementation plan')
    P('Phases are sequential where dependencies exist. Within a phase, tasks can be parallelised across the three people without fixed ownership. Each phase ends with a short written note: what landed, what failed, next blockers.')
    H2('Phase 0 — Repo freeze and definition of done (3–5 days)')
    H3('Goals')
    story.append(bullets(['Agree this plan + schema as the contract for data and modules.', 'Confirm hardware: at least one machine with enough RAM/VRAM for LoRA; one for GCN training; shared experiment log.', 'Pin dependency versions (Python, PyTorch, PyG, transformers, peft, web3.py).'], st))
    H3('Deliverables')
    story.append(bullets(['docs/CarbyneSentinel_Implementation_Plan.pdf (this file).', 'Environment files (requirements / environment.yml) committed.', 'Experiment log template (CSV or markdown): date, commit, metric, notes.'], st))
    H3('Acceptance')
    P('Any teammate can clone, create venv, and run a smoke import of torch + web3.')
    H2('Phase 1 — Bytecode reader and CFG (1.5–2.5 weeks)')
    H3('Research link')
    P('Feature extraction is the barrier named in the report: mempool gives bytecode, not Solidity. Zhuang/SCVHunter start from source; we must own bytecode CFG.')
    H3('Build')
    story.append(numbered(['Disassembler: hex bytecode -> list of (pc, mnemonic, immediates).', 'Basic blocks: split on JUMPDEST / terminators (JUMP, JUMPI, RETURN, REVERT, STOP, SELFDESTRUCT, etc.).', 'CFG edges: fall-through, JUMP, JUMPI true/false when resolvable; mark unresolved edges explicitly.', 'Export: JSON graph + PyG Data (x, edge_index, optional edge_attr).', 'Opcode sequence normalisation for LLM (strip push immediates or hash them; keep length limits).', 'Unit tests on known contracts from SolidiFI / SmartBugs compiled bytecode.'], st))
    H3('Acceptance')
    story.append(bullets(['>= 90% of compiled SolidiFI+SmartBugs samples produce a non-empty CFG without crash.', 'Documented failure modes for contracts that do not parse.', 'Micro-benchmark: p95 CFG build time logged (aim small vs 500 ms budget).'], st))
    H2('Phase 2 — Counting Bloom filter intake (1 week, can overlap Phase 1)')
    H3('Research link')
    P('Haq et al. show CBF mempool fingerprints cut memory under load. We adapt the admission idea only: duplicate / dust filter before expensive models.')
    H3('Build')
    story.append(numbered(['CBF keyed by tx hash (and optionally bytecode hash).', 'Configurable false-positive rate / capacity; expiry or decrement policy.', 'Synthetic flood test: N duplicate txs -> only first proceeds to CFG.', 'Metrics: admitted, rejected, estimated FP rate.'], st))
    H3('Acceptance')
    P('Flood test passes; filter never becomes the latency bottleneck in profiling.')
    H2('Phase 3 — Dataset packaging for training (1–2 weeks)')
    H3('Research link')
    P('SmartBugs + SolidiFI are the named FYP benchmarks. Larger sets (DIVE, DAppSCAN) support pretraining / transfer. Benign pools reduce false-positive blindness.')
    H3('Build')
    story.append(numbered(['Unify training rows into target_schema (snake_case vulnerability vocabulary).', 'Map PascalCase processor labels (AccessControl, etc.) -> schema vocab.', 'Stratified train/val/test splits; keep parent/transform pairs in the same split later.', 'Export graphs + opcode sequences to on-disk caches (do not rebuild every epoch).', 'Publish class_counts / imbalance report next to reports/figures.'], st))
    H3('Acceptance')
    P('One command rebuilds train caches from data/processed + processed/master_dataset.json. Split manifests committed.')
    H2('Phase 4 — Class-imbalance augmentation + obfuscation dataset (ongoing; first useful batch 2–3 weeks)')
    H3('Research link')
    P('OBFPROBE shows detectors collapse under deep obfuscation. FinDet shows bytecode adversaries matter. Our contribution: verified original <-> transformed pairs with schema fields, used both to rebalance minority classes and to measure evasion.')
    H3('Technique ladder (apply in order)')
    story.append(table(['Level', 'Examples', 'Severity', 'Verify'], [['lexical', 'identifier rename, comment/noise, whitespace', 'light', 'compile + same tests'], ['structural', 'dead code, dummy functions, reorder independent stmts', 'light/moderate', 'compile + tests'], ['control_flow', 'opaque predicates, flatten simple branches', 'moderate', 'PoC / unit still red'], ['data_flow', 'temp vars, equivalent arithmetic rewrites', 'moderate', 'PoC still holds'], ['contract_level', 'wrapper / proxy-style indirection (careful)', 'aggressive', 'fork-replay if available']], st, [3.0 * cm, 5.5 * cm, 2.8 * cm, 4.2 * cm]))
    story.append(Paragraph('Table 3. Transformation ladder.', st['caption']))
    H3('Process for each variant')
    story.append(numbered(['Select seed from minority or priority class (prefer SolidiFI/SmartBugs for line truth).', 'Apply one technique set; record techniques + level + severity.', 'Compile; if fail, discard or repair once.', 'Run exploit verification (Foundry test / replay). Set exploit_verified_after_transform.', 'Write JSONL row with parent_contract_id set; never silently overwrite seed.', 'Prefer augmenting minority classes first.'], st))
    H3('Acceptance (first release)')
    story.append(bullets(['At least 200 verified transformed vulnerable samples spanning >= 4 classes.', 'Every published transformed row has exploit_verified_after_transform=true OR an explicit fail log.', 'Distribution report updated after each batch.'], st))
    H2('Phase 5 — Train GCN (1.5–2.5 weeks)')
    H3('Build')
    story.append(numbered(['Dataset class -> PyG Batch loader from cached graphs.', 'Train multi-label or primary-label classifier (start with primary_vulnerability_type + binary vulnerable).', 'Class weights / focal loss; early stopping on val F1 macro.', 'Save best.pt + metrics JSON; plot training curves (B&W ok).', 'Export ONNX or TorchScript optional for faster inference later.'], st))
    H3('Acceptance')
    P('Val macro-F1 improves over majority baseline. Per-class recall table committed. Inference time for median CFG logged.')
    H2('Phase 6 — LoRA Qwen2.5-Coder (2–3 weeks)')
    H3('Build')
    story.append(numbered(['Freeze base; attach LoRA via PEFT.', 'Supervised examples: opcode sequence / snippet -> label or short rationale (rationale only if human-approved; do not auto-LLM invent explanations into dataset).', 'Optional: FinDet-style multi-sample decoding with agreement score as uncertainty proxy.', 'Eval: accuracy / F1 on held-out SmartBugs+SolidiFI; latency with generation capped (max new tokens small).', 'Provide fallback heuristic scorer if model unload.'], st))
    H3('Acceptance')
    P('LoRA adapter loads; offline eval script prints metrics; p95 LLM branch time measured with fixed token budget.')
    H2('Phase 7 — Fusion + thresholds (1 week)')
    story.append(numbered(['Implement Fuse(gcn, llm, fingerprint) -> risk (roadmap Step 5).', 'Sweep thresholds on validation; pick operating point (precision/recall trade-off).', 'Ablation table: GCN / LLM / fingerprint / Fuse combinations.', 'Calibrate score (Platt / isotonic) if needed for human-readable probabilities.'], st))
    H3('Acceptance')
    P('Ablation table exists; fused model not worse than best single branch on macro-F1.')
    H2('Phase 8 — Mempool wiring on Sepolia + Firebase alerts (1.5–2 weeks)')
    H3('Build')
    story.append(numbered(['WebSocket pending subscription; reconnect within 3 s (NFR).', 'Pipeline: CBF -> bytecode/CFG -> fingerprint + GCN + LLM -> Fuse -> flag/log.', 'Async Firebase write for each alert (tx_hash, scores, latency, ts) — not on critical path.', 'Structured logs (JSON): tx hash, scores, latency breakdown, errors.', 'Replay mode: feed recorded pending fixtures without live node.'], st))
    H3('Acceptance')
    P('End-to-end latency histogram on replay + live soak (document p50/p95). Target p95 < 500 ms on agreed hardware; if missed, document bottleneck and mitigation (quantisation, skip LLM on low GCN score, etc.). Firebase receives alerts without blocking the hot path.')
    H2('Phase 9 — Evaluation campaign (2 weeks)')
    story.append(table(['Track', 'Data', 'Metrics'], [['Detection', 'SmartBugs curated + SolidiFI', 'Accuracy, P, R, F1, per-class recall, FP rate'], ['Ablation', 'Same', 'GCN vs LLM vs Fuse'], ['Evasion', 'Obfuscation pairs', 'Detection drop vs severity; verified subset only'], ['Intent', 'DeFi-Intent-Bench', '3-way accuracy (exploit/transfer/arb)'], ['Latency', 'Replay + Sepolia', 'p50/p95 end-to-end and per stage'], ['Intake', 'Synthetic flood', 'Admit/reject counts; memory']], st, [3.0 * cm, 5.5 * cm, 7.0 * cm]))
    story.append(Paragraph('Table 4. Evaluation tracks.', st['caption']))
    H3('Acceptance')
    P('Results chapter numbers come from this campaign only. No invented metrics in the report.')
    H2('Phase 10 — Dashboard, AgentGuard, publish, write-up')
    story.append(bullets(['Dashboard (Step 10): Firebase-backed live/replay score screen for demos.', 'AgentGuard (Step 8): wire same Steps 1-5 brain to agent-payment fixtures; small-scale demo.', 'Bridge Adapter (Step 9): 1-2 page design note only — no implementation.', 'Scale obfuscation benchmark (Step 11) + enrich DeFi-Intent-Bench (Step 12) as time allows.', 'README: offline eval + live watcher + dashboard.', 'Optional Step 14: publish obfuscation (+ intent) subset to Zenodo / Hugging Face.', 'Step 15: sync main.tex results; defense prep; live demo.'], st))
    H1('7. Module checklist (engineering)')
    story.append(table(['Module', 'Inputs', 'Outputs', 'Tests'], [['mempool_listener', 'WS RPC', 'raw tx objects', 'reconnect, fixture replay'], ['cbf_intake', 'tx hash / code hash', 'admit/reject', 'flood duplicates'], ['disasm_cfg', 'bytecode', 'CFG + opcodes', 'golden contracts'], ['gcn_model', 'PyG graph', 'score/embedding', 'overfit tiny set; val metrics'], ['llm_lora', 'opcode text', 'score / label', 'token budget; stub fallback'], ['fingerprint', 'opcodes/CFG stats', 'disguise score', 'benign vs obfuscated pairs'], ['fusion', 'gcn+llm+fp scores', 'risk', 'threshold sweep + ablations'], ['augment_obf', 'seed contract', 'variant + schema fields', 'verify flag'], ['eval_runner', 'split manifests', 'metrics JSON', 'CI smoke'], ['alerter', 'risk event', 'log + Firebase doc', 'async write; alert schema'], ['dashboard', 'Firebase alerts', 'live UI', 'demo replay mode'], ['agentguard', 'agent payment intent', 'same fusion risk', 'fixture small-scale']], st, [3.2 * cm, 3.5 * cm, 4.0 * cm, 4.8 * cm]))
